package ru.kryuch.krtg.searcher.controller;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RequestParam;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import ru.kryuch.krtg.searcher.integration.tg.dto.ChatResponse;import ru.kryuch.krtg.searcher.service.TelegramMessagingService;import ru.kryuch.krtg.searcher.service.TgAccountService;import ru.kryuch.krtg.searcher.type.SendMessageStatus;import java.util.List;import java.util.stream.Collectors;@Controller@RequiredArgsConstructor@RequestMapping("/upload")@Slf4jpublic class UploadController {    private final TgAccountService tgAccountService;    private final TelegramMessagingService telegramMessagingService;    @GetMapping("/")    public String list(Model model) {        model.addAttribute("text", "");        model.addAttribute("page", "upload");        model.addAttribute("tgAccounts", tgAccountService.getAll());        if (model.containsAttribute("successMessage")) {            model.addAttribute("successMessage", model.getAttribute("successMessage"));        }        if (model.containsAttribute("errorMessage")) {            model.addAttribute("errorMessage", model.getAttribute("errorMessage"));        }        return "index";    }    @PostMapping("/")    public String add(@RequestParam("text") String text, @RequestParam("tgAccountIds") List <Integer> tgAccountIds,                      RedirectAttributes redirectAttributes) {        log.info("UploadController::add (text length {}, tgAccountIds = {}, redirectAttribute={}", text.length(), tgAccountIds, redirectAttributes);        if (text == null || text.trim().isEmpty()) {            redirectAttributes.addFlashAttribute("error", "Текст не может быть пустым");            return "redirect:/upload/";        }        List<ChatResponse> chats = telegramMessagingService.createNewContacts(text, tgAccountIds.get(0));        String successMessage =  chats.stream()                        .filter(chatInfo -> chatInfo.getStatus().equals(SendMessageStatus.SUCCESS))                        .map(ChatResponse::getUsername)                        .collect(Collectors.joining(", "));        String errorMessage =  chats.stream()                        .filter(chatInfo -> chatInfo.getStatus().equals(SendMessageStatus.ERROR) || chatInfo.getStatus().equals(SendMessageStatus.SKIP))                        .map(ChatResponse::getUsername)                        .collect(Collectors.joining(", "));        if (!successMessage.isEmpty()) {            redirectAttributes.addFlashAttribute("successMessage", "Текст отправлен контактам: " + successMessage);        }        if (!errorMessage.isEmpty()) {            redirectAttributes.addFlashAttribute("errorMessage", "Текст не отправлен контактам: " + errorMessage);        }        return "redirect:/upload/";    }}